use vstd::prelude::*;

verus! {
    /// Solve whether k back‐and‐forth trips of length `a` are possible
    /// given tank capacity `b` and single station at distance `f` from the start.
    ///
    /// Returns:
    ///   - -1  if the itinerary is impossible
    ///   -  0  if it is possible but no refuel at the station is ever needed
    ///   -  1  if it is possible and at least one refuel at the station is needed
    ///
    fn solve(a: i8, b: i8, f: i8, k: i8) -> (result: i8)
        requires
            // input assumptions
            a > 0,
            b > 0,
            f > 0,
            f < a,
            k > 0,
        ensures
            // result is exactly one of -1, 0, or 1
            result == -1 || (0 <= result && result <= 1),
            // if feasible (not -1), we never claim more refuels than trips
            result <= k,
    {
        let mut ans: i8 = 0;    // our answer accumulator: either stays 0 or goes to 1
        let mut fuel: i8 = b;   // current fuel in tank

        // Pre‐compute the two key distances:
        let dist1: i8 = f;        // distance from start‐endpoint to station
        let dist2: i8 = a - f;    // distance from station to far‐endpoint

        // We will iterate through the k journeys, numbered i = 1..=k.
        // On odd i we go start→end, on even i we go end→start.
        let mut i: i8 = 1;
        while i <= k
            invariant
                // 1 ≤ i ≤ k+1 so that (k+1 – i) is a valid decreases measure
                1 <= i && i <= k + 1,
                // ans is always 0 or 1
                0 <= ans && ans <= 1,
                // fuel is always non-negative and ≤ b
                0 <= fuel && fuel <= b,
            decreases ((k + 1 - i) as nat),
        {
            // If we've advanced past k, break
            if i == k + 1 {
                break;
            }

            if i % 2 != 0 {
                // Odd trip: starting at "0", going toward "a".
                // First leg: from current endpoint to station
                if fuel < dist1 {
                    return -1;
                }
                fuel = fuel - dist1;

                if i == k {
                    // Last trip ends at far endpoint
                    if fuel < dist2 {
                        return -1;
                    }
                    fuel = fuel - dist2;
                } else {
                    // Not the last trip: we must then continue
                    // to the far endpoint and perhaps refuel there.
                    if fuel < dist2 {
                        // we need a top‐up at this station visit
                        ans = 1;
                        fuel = b;
                    }
                    fuel = fuel - dist2;
                }

            } else {
                // Even trip: starting at "a", going back toward "0".
                // First leg: from far endpoint to station
                if fuel < dist2 {
                    return -1;
                }
                fuel = fuel - dist2;

                if i == k {
                    // Last trip ends at start endpoint
                    if fuel < dist1 {
                        return -1;
                    }
                    fuel = fuel - dist1;
                } else {
                    // Not the last trip: we must continue back
                    // to the start‐endpoint and perhaps refuel then.
                    if fuel < dist1 {
                        ans = 1;
                        fuel = b;
                    }
                    fuel = fuel - dist1;
                }
            }

            i = i + 1;
        }

        // At this point, we have successfully completed k trips.
        ans
    }
}

